import assert from 'node:assert/strict';
import {lanes as eight} from './maintenance-eight-lanes.mjs';
import {identity} from './model-settings.mjs';
export const lanes={...eight,inspectSourceCache:{key:'source_cache_inventory',begin:()=>({...identity})}};
// Deliberately uses the caller's public boundary, including real factory owners.
export async function verifySeventyTwoDirections(request){let count=0,oldCount=0;for(const [old,a]of Object.entries(lanes))for(const [newer,b]of Object.entries(lanes)){if(old===newer)continue;const ready=(await request(old,a.begin()))[a.key];assert.ok(old==='inspectSourceCache'?ready.status==='reported':ready.reference,old);const next=(await request(newer,b.begin()))[b.key];assert.ok(newer==='inspectSourceCache'?next.status==='reported':next.reference,newer);if(old!=='inspectSourceCache'){const q=a.change?{action:'save',...identity,reference:ready.reference,change:a.change}:a.changes?{action:'save',...identity,reference:ready.reference,changes:a.changes}:old==='memoryForget'?{action:'confirm',reference:ready.reference}:{action:'confirm',...identity,reference:ready.reference};const result=(await request(old,q))[a.key];assert.ok(['invalidated','unavailable','not-dispatched'].includes(result.state),`${old} after ${newer}: ${result.state}`);}if(old!=='inspectSourceCache'&&newer!=='inspectSourceCache')oldCount++;count++;}assert.equal(count,72);assert.equal(oldCount,56);return count;}
export async function verifySeventyTwoBusyDirections(request,control){let pairs=0;for(const [old,a]of Object.entries(lanes)){await control.hold();const pending=request(old,a.begin());await control.entered();try{const before=await control.snapshot();for(const [newer,b]of Object.entries(lanes)){if(old===newer)continue;const v=(await request(newer,b.begin()))[b.key];assert.equal(newer==='inspectSourceCache'?v.status:v.state,'busy',`${old} holds, ${newer} refused`);assert.deepEqual(await control.snapshot(),before,'Busy must have no hook/cancel/raw I/O');pairs++;}}finally{await control.release();}await pending;}assert.equal(pairs,72);return pairs;}
